    $last = $number % 10;
    $word = ($last_two >= 11 && $last_two <= 14) ? 'записей'
        : ($last === 1 ? 'запись' : (($last >= 2 && $last <= 4) ? 'записи' : 'записей'));
    return number_format_i18n($number) . ' ' . $word;
};

$zinchenko_pdf_url = static function ($file) {
    return trailingslashit(get_template_directory_uri()) . 'assets/zinchenko/'
        . rawurlencode('Статьи') . '/' . rawurlencode($file);
};

