<script>
(function () {
  var root = document.querySelector('.zinchenko-page');
  if (!root) return;

  function showAnchor() {
    var id = decodeURIComponent(window.location.hash.slice(1));
    var target = id ? document.getElementById(id) : null;
    if (!target) return;
    var group = target.closest('.zinchenko-list');
    if (group) group.open = true;
  }
  window.addEventListener('hashchange', showAnchor);
  showAnchor();

  var viewer = document.getElementById('zinchenko-pdf-viewer');
  var frame = document.getElementById('zinchenko-reader-frame');
  var title = document.getElementById('zinchenko-reader-title');
  var link = document.getElementById('zinchenko-reader-link');
  root.querySelectorAll('.zinchenko-pdf-show').forEach(function (button) {
    button.addEventListener('click', function () {
      title.textContent = button.dataset.pdfTitle;
      frame.title = 'Просмотр PDF: ' + button.dataset.pdfTitle;
      frame.src = button.dataset.pdfUrl;
      link.href = button.dataset.pdfUrl;
      viewer.hidden = false;
      window.location.hash = 'zinchenko-pdf-viewer';
    });
  });
}());
</script>

